Here is the commit message:
LUCENE-6233: speed up CheckIndex when the index has term
 vectors

git-svn-id: https://svn.apache.org/repos/asf/lucene/dev/trunk@1658831 13f79535-47bb-0310-9956-ffa450edef68

Here is the root cause:
The root cause of the bug was the inefficiency in the `CheckIndex` process when handling indexes that contain term vectors. The existing implementation was slow due to the way it processed term vectors, leading to longer execution times during index checks. This inefficiency was particularly pronounced when retrieving minimum and maximum terms, as well as during integrity checks, which were not optimized for term vector scenarios.

Here is the patch:
    *  time to run. */
   public Status checkIndex(List<String> onlySegments) throws IOException {
     ensureOpen();
+    long startNS = System.nanoTime();
     NumberFormat nf = NumberFormat.getInstance(Locale.ROOT);
     SegmentInfos sis = null;
     Status result = new Status();
     result.dir = dir;
     String[] files = dir.listAll();
     String lastSegmentsFile = SegmentInfos.getLastCommitSegmentsFileName(files);
     if (lastSegmentsFile == null) {
       throw new IndexNotFoundException("no segments* file found in " + dir + ": files: " + Arrays.toString(files));
     }
     try {
       // Do not use SegmentInfos.read(Directory) since the spooky
       // retrying it does is not necessary here (we hold the write lock):
       sis = SegmentInfos.readCommit(dir, lastSegmentsFile);
     } catch (Throwable t) {
       if (failFast) {
         IOUtils.reThrow(t);
       }
       msg(infoStream, "ERROR: could not read any segments file in directory");
       result.missingSegments = true;
       if (infoStream != null)
         t.printStackTrace(infoStream);
       return result;
     }

     // find the oldest and newest segment versions
     Version oldest = null;
     Version newest = null;
     String oldSegs = null;
     for (SegmentCommitInfo si : sis) {
       Version version = si.info.getVersion();
       if (version == null) {
         // pre-3.1 segment
         oldSegs = "pre-3.1";
       } else {
         if (oldest == null || version.onOrAfter(oldest) == false) {
           oldest = version;
         }
         if (newest == null || version.onOrAfter(newest)) {
           newest = version;
         }
       }
     }

     final int numSegments = sis.size();
     final String segmentsFileName = sis.getSegmentsFileName();
     // note: we only read the format byte (required preamble) here!
     IndexInput input = null;
     try {
       input = dir.openInput(segmentsFileName, IOContext.READONCE);
     } catch (Throwable t) {
       if (failFast) {
         IOUtils.reThrow(t);
       }
       msg(infoStream, "ERROR: could not open segments file in directory");
       if (infoStream != null)
         t.printStackTrace(infoStream);
       result.cantOpenSegments = true;
       return result;
     }
     int format = 0;
     try {
       format = input.readInt();
     } catch (Throwable t) {
       if (failFast) {
         IOUtils.reThrow(t);
       }
       msg(infoStream, "ERROR: could not read segment file version in directory");
       if (infoStream != null)
         t.printStackTrace(infoStream);
       result.missingSegmentVersion = true;
       return result;
     } finally {
       if (input != null)
         input.close();
     }

     String sFormat = "";
     boolean skip = false;

     result.segmentsFileName = segmentsFileName;
     result.numSegments = numSegments;
     result.userData = sis.getUserData();
     String userDataString;
     if (sis.getUserData().size() > 0) {
       userDataString = " userData=" + sis.getUserData();
     } else {
       userDataString = "";
     }

     String versionString = "";
     if (oldSegs != null) {
       if (newest != null) {
         versionString = "versions=[" + oldSegs + " .. " + newest + "]";
       } else {
         versionString = "version=" + oldSegs;
       }
     } else if (newest != null) { // implies oldest != null
       versionString = oldest.equals(newest) ? ( "version=" + oldest ) : ("versions=[" + oldest + " .. " + newest + "]");
     }

     msg(infoStream, "Segments file=" + segmentsFileName + " numSegments=" + numSegments
         + " " + versionString + " id=" + StringHelper.idToString(sis.getId()) + " format=" + sFormat + userDataString);

     if (onlySegments != null) {
       result.partial = true;
       if (infoStream != null) {
         infoStream.print("\nChecking only these segments:");
         for (String s : onlySegments) {
           infoStream.print(" " + s);
         }
       }
       result.segmentsChecked.addAll(onlySegments);
       msg(infoStream, ":");
     }

     if (skip) {
       msg(infoStream, "\nERROR: this index appears to be created by a newer version of Lucene than this tool was compiled on; please re-compile this tool on the matching version of Lucene; exiting");
       result.toolOutOfDate = true;
       return result;
     }


     result.newSegments = sis.clone();
     result.newSegments.clear();
     result.maxSegmentName = -1;

     for(int i=0;i<numSegments;i++) {
       final SegmentCommitInfo info = sis.info(i);
       int segmentName = Integer.parseInt(info.info.name.substring(1), Character.MAX_RADIX);
       if (segmentName > result.maxSegmentName) {
         result.maxSegmentName = segmentName;
       }
       if (onlySegments != null && !onlySegments.contains(info.info.name)) {
